/* CSS PART 1 OF 2 */

:root {
  --forest: #203f32;
  --forest-deep: #152e25;
  --sage: #8c9d78;
  --sage-light: #e9eee4;
  --earth: #b47b50;
  --cream: #f7f6ef;
  --white: #ffffff;
  --ink: #25332b;
  --muted: #68736a;
  --line: #dce2d9;
  --font-heading: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Arial, sans-serif;
  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --radius: 4px;
  --shadow: 0 14px 40px rgba(24, 46, 34, .12);
}

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, textarea, select {
  font: inherit;
}

button, a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--earth);
  outline-offset: 4px;
}

::selection {
  background: var(--sage);
  color: var(--forest-deep);
}

h1, h2, h3, h4, p {
  margin-top: 0;
}

h1, h2, h3 {
  color: var(--forest-deep);
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -.035em;
}

h1 {
  font-size: clamp(3.1rem, 7.5vw, 6.8rem);
}

h2 {
  font-size: clamp(2.4rem, 5vw, 4.2rem);
}

h3 {
  font-size: clamp(1.5rem, 2.5vw, 2rem);
}

p {
  color: var(--muted);
}

.container {
  width: min(100% - var(--gutter) * 2, var(--container));
  margin-inline: auto;
}

.section {
  padding-block: clamp(76px, 10vw, 132px);
}

.section-kicker {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--earth);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.section-kicker::before {
  width: 30px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 24px;
}

.section-intro {
  max-width: 620px;
  font-size: 1.08rem;
  line-height: 1.85;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--earth);
  color: var(--forest);
  font-size: .85rem;
  font-weight: 700;
}

.text-link::after {
  content: "↗";
  transition: transform .2s ease;
}

.text-link:hover::after {
  transform: translate(3px, -3px);
}

/* Header and navigation */

.site-header {
  position: relative;
  z-index: 20;
  background: var(--cream);
  border-bottom: 1px solid rgba(32, 63, 50, .1);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  flex-shrink: 0;
}

.brand-logo {
  width: 54px;
  height: 54px;
  object-fit: contain;
}

.brand-name {
  display: flex;
  flex-direction: column;
  color: var(--forest);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  line-height: 1.05;
}

.brand-name small {
  margin-top: 5px;
  color: var(--muted);
  font-family: var(--font-body);
  font-size: .57rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 40px);
}

.primary-nav a:not(.button) {
  color: var(--ink);
  font-size: .82rem;
  font-weight: 600;
  transition: color .2s ease;
}

.primary-nav a:not(.button):hover {
  color: var(--earth);
}

.header-cta {
  white-space: nowrap;
}

/* Buttons */

.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 15px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--forest);
  color: var(--white);
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .075em;
  text-align: center;
  text-transform: uppercase;
  transition: background .2s ease, color .2s ease, border-color .2s ease, transform .2s ease;
}

.button::after {
  content: "↗";
  font-size: 1rem;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--forest-deep);
}

.button-light {
  border-color: rgba(255, 255, 255, .8);
  background: transparent;
  color: var(--white);
}

.button-light:hover {
  background: var(--white);
  color: var(--forest);
}

.button-secondary {
  border-color: var(--forest);
  background: transparent;
  color: var(--forest);
}

.button-secondary:hover {
  background: var(--forest);
  color: var(--white);
}

/* Full-bleed hero */

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, 82vh);
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--forest-deep);
  color: var(--white);
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 52%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(15, 34, 25, .88) 0%,
    rgba(15, 34, 25, .72) 40%,
    rgba(15, 34, 25, .22) 100%
  );
  content: "";
}

.hero-content {
  width: min(760px, 75%);
  padding-block: 110px;
  color: var(--white);
}

.hero .section-kicker {
  color: #d9b58f;
}

.hero h1 {
  margin-bottom: 26px;
  color: var(--white);
}

.hero-description {
  max-width: 540px;
  margin-bottom: 36px;
  color: rgba(255, 255, 255, .88);
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

/* Trust and business introduction */

.trust-strip {
  background: var(--forest);
  color: var(--white);
}

.trust-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(255, 255, 255, .92);
  font-size: .82rem;
  font-weight: 600;
}

.trust-mark {
  color: #d4b18a;
  font-size: 1.15rem;
}

.intro-section {
  background: var(--cream);
}

.intro-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  align-items: center;
  gap: clamp(50px, 9vw, 130px);
}

.intro-copy h2 {
  max-width: 570px;
}

.intro-copy p {
  max-width: 560px;
  margin-bottom: 28px;
}

.intro-note {
  margin-top: 32px;
  padding: 22px 25px;
  border-left: 3px solid var(--sage);
  background: var(--sage-light);
  color: var(--forest);
  font-family: var(--font-heading);
  font-size: 1.2rem;
  line-height: 1.5;
}

.intro-visual {
  position: relative;
  min-height: 450px;
  background: var(--sage-light);
}

.intro-visual img {
  width: 100%;
  height: 450px;
  object-fit: cover;
}

/* Services */

.services-section {
  background: #edf0e8;
}

.services-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 58px;
}

.services-heading .section-heading {
  margin-bottom: 0;
}

.services-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: start;
}

.services-copy {
  max-width: 480px;
}

.services-copy p {
  line-height: 1.9;
}

.service-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid rgba(32, 63, 50, .2);
}

.service-item {
  display: flex;
  min-height: 94px;
  align-items: center;
  gap: 16px;
  padding: 20px 12px;
  border-bottom: 1px solid rgba(32, 63, 50, .2);
}

.service-number {
  color: var(--earth);
  font-family: var(--font-heading);
  font-size: 1.15rem;
}

.service-item h3 {
  margin: 0;
  font-family: var(--font-body);
  font-size: .94rem;
  font-weight: 600;
  letter-spacing: 0;
}

/* Local sourcing and care */

.local-section {
  background: var(--forest-deep);
  color: var(--white);
}

.local-section h2 {
  color: var(--white);
}

.local-section p {
  color: rgba(255, 255, 255, .75);
}

.local-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(48px, 8vw, 110px);
}

.local-visual {
  min-height: 400px;
  overflow: hidden;
}

.local-visual img {
  width: 100%;
  height: 440px;
  object-fit: cover;
}

.local-copy {
  max-width: 530px;
}

.local-copy .section-kicker {
  color: #d9b58f;
}

.local-copy h2 {
  margin-bottom: 24px;
}

.local-copy p {
  margin-bottom: 28px;
  font-size: 1.04rem;
  line-height: 1.9;
}

.local-detail {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 32px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, .2);
  color: rgba(255, 255, 255, .88);
  font-size: .86rem;
}

.local-detail::before {
  width: 26px;
  height: 1px;
  flex: 0 0 26px;
  background: var(--earth);
  content: "";
}
