/* CSS PART 2 OF 2 */

/* Contact and conversion */

.contact-section {
  padding-block: clamp(80px, 10vw, 130px);
  background: var(--sage-light);
}

.contact-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: clamp(45px, 8vw, 110px);
  align-items: start;
}

.contact-copy {
  max-width: 470px;
}

.contact-copy h2 {
  margin-bottom: 24px;
}

.contact-copy p {
  line-height: 1.9;
}

.contact-emphasis {
  margin-top: 32px;
  padding: 24px;
  border-left: 3px solid var(--earth);
  background: var(--cream);
  color: var(--forest);
  font-family: var(--font-heading);
  font-size: 1.35rem;
  line-height: 1.45;
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  background: var(--white);
  box-shadow: var(--shadow);
}

.form-heading {
  margin-bottom: 30px;
}

.form-heading h3 {
  margin-bottom: 8px;
}

.form-heading p {
  margin-bottom: 0;
  font-size: .9rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--forest);
  font-size: .78rem;
  font-weight: 700;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: var(--cream);
  color: var(--ink);
  font-size: .92rem;
}

.form-field textarea {
  min-height: 140px;
  resize: vertical;
}

.form-field input:focus-visible,
.form-field select:focus-visible,
.form-field textarea:focus-visible {
  border-color: var(--forest);
  outline: 3px solid rgba(140, 157, 120, .4);
  outline-offset: 2px;
}

.form-submit {
  width: 100%;
  margin-top: 24px;
  cursor: pointer;
}

.form-note {
  margin: 14px 0 0;
  color: var(--muted);
  font-size: .75rem;
  line-height: 1.6;
}

/* Footer */

.site-footer {
  padding-block: 65px 25px;
  background: var(--forest-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 48px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-name small {
  color: rgba(255, 255, 255, .65);
}

.footer-description {
  max-width: 340px;
  margin-top: 22px;
  color: rgba(255, 255, 255, .7);
  font-size: .9rem;
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 35px;
}

.footer-nav a {
  color: rgba(255, 255, 255, .85);
  font-size: .82rem;
}

.footer-nav a:hover {
  color: #d9b58f;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, .17);
  color: rgba(255, 255, 255, .55);
  font-size: .72rem;
}

/* Responsive navigation */

.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Tablet */

@media (max-width: 900px) {
  :root {
    --gutter: 32px;
  }

  .header-inner {
    min-height: 76px;
  }

  .menu-toggle {
    display: flex;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 12px var(--gutter) 25px;
    border-top: 1px solid var(--line);
    background: var(--cream);
    box-shadow: 0 12px 20px rgba(24, 46, 34, .1);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
  }

  .primary-nav .header-cta {
    margin-top: 15px;
  }

  .hero {
    min-height: 650px;
  }

  .hero-content {
    width: 90%;
  }

  .intro-layout,
  .local-layout {
    grid-template-columns: 1fr 1fr;
    gap: 36px;
  }

  .services-layout {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .contact-copy {
    max-width: 650px;
  }

  .trust-inner {
    flex-wrap: wrap;
    justify-content: center;
    padding-block: 24px;
  }
}

/* Mobile */

@media (max-width: 600px) {
  :root {
    --gutter: 22px;
  }

  body {
    font-size: 15px;
  }

  .section {
    padding-block: 72px;
  }

  .header-inner {
    min-height: 70px;
    gap: 12px;
  }

  .brand-logo {
    width: 43px;
    height: 43px;
  }

  .brand-lockup {
    gap: 9px;
  }

  .brand-name {
    font-size: 1.08rem;
  }

  .brand-name small {
    font-size: .5rem;
  }

  .primary-nav {
    max-height: calc(100vh - 70px);
    overflow-y: auto;
    overflow-x: hidden;
  }

  .primary-nav a {
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  h1 {
    font-size: clamp(2.8rem, 13vw, 4.5rem);
  }

  h2 {
    font-size: clamp(2.35rem, 10vw, 3.3rem);
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, 88svh);
    align-items: end;
  }

  .hero-media {
    object-position: 58% center;
  }

  .hero::before {
    background: linear-gradient(
      0deg,
      rgba(15, 34, 25, .92) 0%,
      rgba(15, 34, 25, .72) 48%,
      rgba(15, 34, 25, .16) 100%
    );
  }

  .hero-content {
    width: 100%;
    padding-block: 100px 65px;
  }

  .hero-description {
    font-size: 1rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .trust-inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 17px;
    padding-block: 25px;
  }

  .intro-layout,
  .local-layout {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .intro-visual {
    min-height: 300px;
  }

  .intro-visual img {
    height: 300px;
  }

  .services-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 35px;
  }

  .services-layout {
    gap: 25px;
  }

  .service-list {
    grid-template-columns: 1fr;
  }

  .service-item {
    min-height: 76px;
  }

  .local-visual {
    min-height: 280px;
  }

  .local-visual img {
    height: 300px;
  }

  .contact-form {
    padding: 24px 19px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .form-field-full {
    grid-column: auto;
  }

  .footer-main {
    flex-direction: column;
    gap: 32px;
  }

  .footer-nav {
    flex-direction: column;
    gap: 14px;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
}

/* Reduced motion and accessible interaction */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

@media (hover: none) {
  .button:hover,
  .text-link:hover::after {
    transform: none;
  }
}
```
